    { id = "spiritbeast_tigerloa", lookID = "tigerloa", family = "spiritbeast", modelGroup = "Great Spirit Tigers", name = "Сул'рака", subTitle = "Фиолетовая теневая пантера Лоа по следам", npcID = 210868, rarity = "SECRET", zone = "Изумрудный Сон", mapID = 2200, npcIDs = {210868}, coords = {{x=63.0,y=67.0,note="Юго-восточный маршрут Изумрудного Сна"}}, npcs = {{id=210868,name="Sul'raka",level="70",tag="Элита",zone="Изумрудный Сон"}}, respawn = "15–30 минут (невидима без ракеты!)", howTo = "Глубоко-фиолетовая полупрозрачная тигрица Лоа в Изумрудном Сне! Бродит в полной невидимости, оставляя на земле «Тяжелые следы». Брось перед свежим следом Осветительную ракету и Замораживающую ловушку!" },
    { id = "spiritbeast_spectralgryphon", lookID = "spectralgryphon", family = "spiritbeast", modelGroup = "Spectral Gryphons", name = "Затерянный спектральный грифон", subTitle = "Призрачный грифон Штормграда (Клик по перу)", npcID = 121567, rarity = "SECRET", zone = "Штормград", mapID = 84, npcIDs = {121567}, coords = {{x=71.2,y=72.5,note="Пёрышко прямо у распорядителя полётов Штормграда!"}}, npcs = {{id=121567,name="Lost Spectral Gryphon",level="10-60",zone="Штормград"}}, respawn = "15–45 минут (клик по Призрачному перу)", howTo = "Прилети к мастеру полётов Штормграда (71.2, 72.5) — даже за Орду под Черепахой/Камуфляжем! Прямо на сене у гнезда лежит «Призрачное перо». Кликни по нему — грифон мгновенно материализуется перед тобой!" },
    { id = "spiritbeast_raptor2_lightning-frost", lookID = "raptor2_lightning-frost", family = "spiritbeast", modelGroup = "Spirit Raptors", name = "Гон", subTitle = "Призрачный ящер Оргриммара (Клик по скорлупе)", npcID = 121571, rarity = "SECRET", zone = "Оргриммар", mapID = 85, npcIDs = {121571}, coords = {{x=35.6,y=69.0,note="Призрачная скорлупа у костра в хижине"}}, npcs = {{id=121571,name="Gon",level="10-60",tag="Особый призыв",zone="Оргриммар"}}, respawn = "15–45 минут (клик по Призрачной скорлупе)", howTo = "Зайди в большую шаманскую хижину на Аллее Духов Оргриммара (35.6, 69.0). У черепов справа на полу лежит маленькая «Спектральная яичная скорлупа». Нажми на неё — появится Гон!" },
    { id = "spiritbeast_wolfdraenor_shadow", lookID = "wolfdraenor_shadow", family = "spiritbeast", modelGroup = "Spirit Wolves", name = "Гара", subTitle = "Волчица Бездны (Секретная цепочка ритуала)", npcID = 88708, rarity = "SECRET", zone = "Долина Призрачной Луны", mapID = 539, npcIDs = {88708,88710}, coords = {{x=28.6,y=35.8,note="Погост у кургана (Старт цепочки)"},{x=56.8,y=21.6,note="Древо столпов для ритуала"}}, npcs = {{id=88708,name="Gara",level="10-40",zone="Долина Призрачной Луны"},{id=88710,name="Lost Netherwolf",level="10-40",zone="Долина Призрачной Луны"}}, respawn = "Мгновенно по завершении личного ритуала (100% гарантия!)", howTo = "Секретный фиолетовый Дух Зверя без конкуренции с другими хантами! Шаг 1: Почеши Гару на погосте (28.6, 35.8) и покажи ей Сумеречную ягоду. Шаг 2: Собери 6 предметов по Дренору для Чучела. Шаг 3: Уложи чучело у могилы Гары, возьми Теневой фонарь с владыки Бездны и войди в мир Бездны у Древа (56.8, 21.6)." },
    { id = "spiritbeast_celestialserpent", lookID = "celestialserpent", family = "spiritbeast", modelGroup = "Astral Cloud Serpents", name = "Элегон", subTitle = "Звёздный астральный облачный змей", npcID = 60410, rarity = "BOSS", zone = "Вершина Кунь-Лай", mapID = 379, npcIDs = {60410}, coords = {{x=59.6,y=39.2,note="Вход в рейд Подземелья Могу'шан"}}, npcs = {{id=60410,name="Elegon",level="Boss",tag="Босс",zone="Подземелья Могу'шан"}}, respawn = "Внутри рейда на любой сложности (100% спавн!)", howTo = "Звёздный дракон Элегон приручается как Дух Зверя (не требует книги облачных змеев, только спек БМ)! Зайди в рейд Подземелья Могу'шан, дойди до 5-го босса и приручи." },
